                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    		FlyBtn.TextColor3 = Color3.fromRGB(255, 100, 100)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            	end
